"""Builds the SERS report for the most recent NAM, LPS and LTA session. Numbers come from the analysis tables (results.json and csv files)."""
import os,json,shutil,pandas as pd
import fr_docs as FD
S=r"C:\Users\sukes\AppData\Local\Temp\claude\C--Users-sukes-Downloads-sukesh\f9c0734c-e0bb-4f52-a4e5-d9f33e9bce00\scratchpad\sersfinal"
FIG=S+r"\figures"; TAB=S+r"\tables"; R=json.load(open(TAB+r"\results.json")); T=pd.read_csv(TAB+r"\target_band_detection.csv"); B=pd.read_csv(TAB+r"\lps_session_reproducible_bands.csv")
OUT=os.path.join(FD.OUT,'07_SERS_Report'); os.makedirs(OUT,exist_ok=True)
n=R['n']; ch=R['chance']
def det(mol):
    t=T[T.molecule==mol]; return t
d=FD.Doc('Surface-Enhanced Raman Spectra of NAM, LPS and LTA on Etched Silicon','Results of the most recent measurement session and whether any biomarker was detected')
d.h1('Executive summary')
d.p(f"In the most recent session, {sum(n[k] for k in ('NAM','LPS','LTA'))} spectra were recorded for NAM ({n['NAM']}), LPS ({n['LPS']}) and LTA ({n['LTA']}) on etched silicon, with {n['blank']} spectra of the bare etched substrate (blank) for comparison. No biomarker was detected with confidence. NAM and LTA show nothing that separates them from the blank or from chance. LPS gives one lead worth following up: a reproducible set of ten bands appears on {R['n_carry']} of the {R['n_lps']} LPS spots and on none of the blank or bare-silicon spectra. This set does not meet the detection rule set for LPS and does not match the bulk LPS spectrum, so it cannot yet be attributed to LPS.")
d.table(['Molecule','Spectra','Outcome','Reason'],[['NAM',n['NAM'],'Not detected','No bulk NAM band is stronger than in the blank, and the hit rate is no better than random positions'],['LPS',n['LPS'],'Lead, not confirmed',f"Ten-band set reproducible on {R['n_carry']} spots and absent from the blank; the two bands required by the detection rule are not both present"],['LTA',n['LTA'],'Not detected','No band above chance; only nine spectra']],[2.4,2.0,3.4,9.0],'Outcome for each molecule.')
d.h1('Objective')
d.p("To test whether the three sepsis-related molecules can be seen by surface-enhanced Raman spectroscopy (SERS) on etched silicon, and to compare what is seen with the reference bulk spectra of the same molecules. SERS is Raman spectroscopy in which the signal of molecules lying on a roughened metal-coated surface is strongly amplified, so that very small amounts can be detected. A biomarker is a substance that may indicate a biological condition; here a molecule counts as detected only if its characteristic peaks appear in the spectra and are absent from the blank.")
d.h1('Data and approach')
d.h2('What was measured')
d.p(f"All spectra were recorded in one session with the same 785 nm Raman instrument used for the bulk reference spectra (B&W Tek i-Raman Plus). Laser power is given as a percentage of the instrument maximum. The blank was recorded first, then NAM, LPS and LTA in turn. Sample concentration, volume and the way each sample was applied were not recorded, and no reference-dye check was made in this session.")
d.table(['Sample','Spectra','Laser power (% of max)','Integration (s)','Accumulations'],[['Blank',n['blank'],'15','10','2'],['NAM',n['NAM'],'15 to 70','5 to 15','2 to 3'],['LPS',n['LPS'],'30 to 50','10 to 15','2'],['LTA',n['LTA'],'10 and 50','10','2']],[3.0,2.2,4.2,3.2,3.2],'Measurements in the session.')
d.h2('How the spectra were analysed')
d.b("The same processing as for the bulk reference spectra: background subtraction, repair of two defective detector pixels, 400 to 1800 cm⁻¹, spike removal, smoothing and baseline removal. The baseline step removes the slowly changing background so that peaks are easier to see.","Processing:")
d.b("A band counts as detected in a spectrum when a peak lies within 5 cm⁻¹ of the target position, is at least three detector pixels wide and rises at least three times the noise above its surroundings.","Detection rule:")
d.b("The bulk reference peaks of each molecule (NAM 541, 829, 870.5, 929, 955, 1023, 1127; LPS 425, 766, 861, 997, 1080; LTA 802, 861.5, 1092, 1459 cm⁻¹) and the SERS bands used for LPS (989 and 1330 cm⁻¹) and LTA (a phosphate band at 1225 to 1250 cm⁻¹ and a lipid band at 1131 or 1450 cm⁻¹).","Targets:")
d.b("Each band is compared with the blank and with bare silicon, and its height relative to the silicon peak is compared with the blank. A chance test shifts all target positions by a random 20 to 80 cm⁻¹ (400 times) to see how often a detection rate as high as the real one occurs by chance.","Comparison:")
d.h1('Results')
d.h2('What every spectrum contains')
d.p(f"Every spectrum is dominated by the crystalline-silicon peak at 518 cm⁻¹ (the instrument reads it 2 to 3 cm⁻¹ below the true value). A broad silicon feature near 935 cm⁻¹ appears in about a third of the spectra and also in bare silicon, so it is not molecular; this matters for NAM, whose 929 and 955 cm⁻¹ targets lie on its edge. The molecular signals are weak and sit on top of the silicon peak. No spectrum is saturated.")
d.figure(FIG+r"\F2_mean_spectra_vs_blank.png","Mean spectrum of each molecule (coloured) with the blank (dark grey) and bare silicon (dashed grey), each scaled to the silicon peak. Red dotted lines mark the target bands. For LPS, the red curve is the mean of the spots that carry the ten-band set.",w=16.4)
d.h2('NAM')
t=det('NAM'); top=t.sort_values('detected_sample',ascending=False).iloc[0]
d.p(f"No bulk NAM peak is found in more than {int(top.detected_sample)} of the {n['NAM']} spectra (the most frequent is {top.band} cm⁻¹, {100*top.detected_sample/n['NAM']:.0f} %), and in every case the NAM spectra are no stronger than the blank. The detection rate over all NAM target positions is {100*ch['NAM']['real']:.1f} %, against {100*ch['NAM']['mean']:.1f} % for random positions (p = {ch['NAM']['p']:.2f}). Peaks found outside silicon change from one spectrum to the next and do not repeat. NAM is not detected. This agrees with the earlier finding for NAM: it has no group that binds strongly to silver, so it is not expected to stay at the surface without a capture agent.")
d.h2('LPS')
t=det('LPS'); d1330=t[t.band.astype(str)=='1330'].iloc[0]
d.p(f"None of the bulk LPS peaks (425, 766, 861, 997, 1080 cm⁻¹) is found, and neither is the SERS band at 989 cm⁻¹. The SERS band at 1330 cm⁻¹ is found in {int(d1330.detected_sample)} of the {n['LPS']} spectra and in none of the blank spectra, but the detection rule needs both 989 and 1330 cm⁻¹, so LPS is not detected by that rule.")
d.p(f"The spectra nevertheless contain more than silicon. Ten bands repeat on {R['n_carry']} of the {R['n_lps']} LPS spots. Their median spectrum-to-spectrum correlation is {R['repro']['carrying_median_r']:.2f}, against {R['repro']['other_LPS_median_r']:.2f} for the other LPS spots, {R['repro']['blank_median_r']:.2f} for the blank and {R['repro']['NAM_median_r']:.2f} for NAM (1.0 would be identical). The spots that carry the set have a weaker silicon peak (median {R['si_carry']:.0f} counts against {R['si_nocarry']:.0f}), as expected if a surface layer covers the silicon. The set is absent from the blank (0 of {n['blank']}) and bare silicon (0 of {R['n_bare']}).")
rows=[[f"{r.mean_position:.0f} ± {r.sd_position:.1f}",f"{100*r.fraction_carrying:.0f} %",f"{100*r.fraction_other_LPS:.0f} %",f"{100*r.fraction_blank:.0f} %",f"{r.median_snr_carrying:.0f}",{785:'794 and 1592 listed as common LPS peaks (no assignment)'}.get(0,'') or {785:'794, common LPS peak, 9 cm⁻¹ away',1592:'1592, common LPS peak'}.get(int(r.band),r.literature).replace(' (LPS-1)','').replace(' (LPS-2)','').replace('in the SERS LPS lists','in published SERS lists')] for _,r in B.iterrows()]
d.table(['Band (cm⁻¹)','On the spots with the set','On other LPS spots','On the blank','Signal-to-noise','Nearest published LPS band'],rows,[2.6,2.6,2.4,2.0,2.2,5.2],'The ten bands that repeat on the LPS spots.')
d.figure(FIG+r"\F7_LPS_band_zooms.png","Four bands of the ten-band LPS set. Thin lines: individual LPS spots that carry the set; red: their mean; grey: the blank mean. All spectra are scaled to the silicon peak.",w=16.4)
d.figure(FIG+r"\F6_LPS_session_band_set.png","How often each band of the set appears in each group of spectra. The set is common on the LPS spots that carry it and rare or absent elsewhere.",w=16.4)
d.p("What this does and does not show. The strongest band, at 1455 cm⁻¹, lies 5 cm⁻¹ above the CH₂/CH₃ deformation listed for SERS of LPS, and the 1330 cm⁻¹ band matches a band at 1330 to 1333 cm⁻¹ in published LPS SERS lists. The 1009 cm⁻¹ band lies 6 to 21 cm⁻¹ from published bands, and the 785 and 1592 cm⁻¹ bands lie at or near peaks (794 and 1592 cm⁻¹) listed as common to commercial endotoxins without an assignment; the other five bands have no match in the checked lists. The mean spectrum of the spots with the set correlates with the bulk LPS reference at only "+f"{R['sim']['LPS']:.2f}"+", no better than with the bulk LTA ("+f"{R['sim']['LTA']:.2f}"+") or NAM ("+f"{R['sim']['NAM']:.2f}"+") references. The pattern is consistent with an organic layer containing CH₂ and CH₃ groups on the silicon, and LPS is one possible source, but it is not an identification.")
d.h2('LTA')
d.p(f"None of the LTA bands is detected above chance: the detection rate over all target positions is {100*ch['LTA']['real']:.1f} % against {100*ch['LTA']['mean']:.1f} % for random positions (p = {ch['LTA']['p']:.2f}). The phosphate region (1225 to 1250 cm⁻¹) gives one detection in nine spectra and the 1092 cm⁻¹ position none. Four of the nine spectra were taken at 10 % power, where the silicon peak is only about 250 to 340 counts and sensitivity is very low. LTA is not detected, but nine spectra and no matching blank are a weak test.")
d.h2('Comparison with chance')
d.figure(FIG+r"\F4_target_band_detection.png","Fraction of spectra in which each target band is detected, for the sample (colour) and the blank (grey).",w=16.4)
d.figure(FIG+r"\F5_chance_test.png","Detection rate over all target positions (coloured line) compared with 400 random shifts of the positions (grey). None of the three exceeds chance.",w=16.4)
d.h1('Interpretation')
d.p("The session does not show a detected biomarker. NAM and LTA give no evidence of surface signal, and the LPS result is a lead rather than a detection: a reproducible, blank-free band pattern that is consistent with an organic layer on silicon but does not match the bulk LPS spectrum. A SERS spectrum can differ from the bulk spectrum in which bands are enhanced, so the lack of overlap is not proof against LPS, but it also does not support it. Two features limit what can be concluded: the blank was recorded about five hours before the first LPS spectrum and eight hours before the LTA spectra, and there is no solvent-only control prepared like the LPS spots, so contamination from preparation or handling cannot be excluded.")
d.h1('Conclusion and next step')
d.p("No molecule was detected with confidence; LPS is the one result worth building on. The most useful next step is to repeat LPS on a fresh substrate with a solvent-only control prepared in the same way and a blank at the start and end of the set, keeping the 50 % power, 15 s, 2 accumulation setting, and to record concentration, volume and application method. Measuring bulk LPS on the same type of silicon would show directly which bands LPS gives there. For NAM, a capture agent on the silver surface is needed before further measurements; for LTA, more spectra at 50 % power or higher with a same-session blank.")
path=os.path.join(OUT,'SERS_Spectra_NAM_LPS_LTA_Report.docx'); d.save(path); print(path)
